import{_ as s,l as i,o as e,c as o,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"严格与强严格 2PL","description":"","frontmatter":{"title":"严格与强严格 2PL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strict-2pl.md","filePath":"cs/strict-2pl.md","lastUpdated":1789023840000}'),E={name:"cs/strict-2pl.md"};function h(_,a,A,P,B,m){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="严格与强严格-2pl" tabindex="-1">严格与强严格 2PL <a class="header-anchor" href="#严格与强严格-2pl" aria-label="Permalink to &quot;严格与强严格 2PL&quot;">​</a></h1><div class="epigraph"><p>严格 2PL 把写锁留到提交，堵住脏读与级联回滚；强严格连读锁也留到提交，调度成为可恢复的严格串行。</p><footer>—— 据 Eswaran et al.；Bernstein 对严格 2PL；Gray and Reuter</footer></div><p><a href="/cs/two-pl">上一课</a>给出增长/收缩两阶段，保证冲突可串行。本课不重画锁点。缺口是收缩太早：写锁在提交前释放，别人读到未提交值，然后你回滚——级联。严格：直到结束才放写锁。强严格（SS2PL）：读写锁都留到结束。MVCC 下一课对照读为何可不加锁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PL 课留下「严格 2PL 顺带挡住脏读」。需要钉术语。可恢复调度：若 i 读了 j 的写，j 必须先提交。级联回滚：j 撤则 i 也要撤。严格 2PL 通过「提交前不放 X 锁」得到可恢复且无级联。强严格再推迟 S 锁，便于提交序与锁点一致。缺口是<strong>锁释放时机相对提交点</strong>。</p><p><span class="marginnote">生产系统几乎都用严格或更严，很少在收缩阶段提前放写锁。死锁概率上升是代价，后课检测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事务提交/中止时一次性释放。隔离级别若允许提前放 S 锁，会换来不可重复读——后课级别表。本课只钉严格族与 2PL 的关系：严格 2PL ⊂ 2PL，仍可串行，且可恢复。</p>',8)),(e(),n(c,null,{default:r(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TWO%5B%222PL%20%E5%8F%AF%E4%B8%B2%E8%A1%8C%22%5D%20--%3E%20ST%5B%22%E4%B8%A5%E6%A0%BC%3A%20%E5%86%99%E9%94%81%E7%95%99%E5%88%B0%E6%8F%90%E4%BA%A4%22%5D%0A%20%20ST%20--%3E%20SS%5B%22%E5%BC%BA%E4%B8%A5%E6%A0%BC%3A%20%E8%AF%BB%E9%94%81%E4%B9%9F%E7%95%99%E5%88%B0%E6%8F%90%E4%BA%A4%22%5D%0A%20%20ST%20--%3E%20REC%5B%22%E5%8F%AF%E6%81%A2%E5%A4%8D%E3%80%81%E6%97%A0%E7%BA%A7%E8%81%94%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>写锁持有到提交，使 wr 边的源头必已持久或尚未被读。这与 <a href="/cs/wal">WAL</a> 配合：未提交写可以 steal 到页上，但别人读不到（锁），UNDO 不必追读者。读锁提前放则允许 rw 在提交前发生，可串行仍可能，重复读不保证。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 SI 当 2PL 的一种。长读挡住写的问题，下一课用多版本缓解。</p><p>后课默认：锁实现常用严格 2PL。只读不想挡写，走 MVCC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>严格 2PL 提交前不放写锁，避免脏读与级联。</li><li>强严格连读锁一起留。</li><li>多版本下一课。</li><li>出处：Bernstein；Eswaran 1976；Gray and Reuter。</li></ul>',7))])}const S=s(E,[["render",h]]);export{f as __pageData,S as default};
